sp_widget.client_script:
api.controller = function($scope, $location) {
  var c = this;
  var params = $location.search();

  c.data.adults = 1;
  c.data.children = 0;
  c.checkInDate = null;
  c.checkOutDate = null;
  c.showModal = false;
  c.bookingConfirmed = false;
  c.isSubmitting = false;

  if (c.data.isLoggedIn) {
    c.data.guestName = c.data.userName;
    c.data.guestEmail = c.data.userEmail;
  }

  c.toLocalDateStr = function(val) {
    if (!val) return "";
    if (typeof val === "string") return val.substring(0, 10);
    if (val instanceof Date && !isNaN(val.getTime())) {
      var y = val.getFullYear();
      var m = ("0" + (val.getMonth() + 1)).slice(-2);
      var d = ("0" + val.getDate()).slice(-2);
      return y + "-" + m + "-" + d;
    }
    return String(val).substring(0, 10);
  };

  function parseDate(value) {
    if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
    var parts = value.split("-");
    var date = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    if (date.getFullYear() !== parseInt(parts[0], 10) || date.getMonth() !== parseInt(parts[1], 10) - 1 || date.getDate() !== parseInt(parts[2], 10)) {
      return null;
    }
    return date;
  }

  function selectRoomByType(roomType) {
    if (!roomType || !c.data.rooms) return;
    var requestedType = String(roomType).toLowerCase().trim();
    for (var i = 0; i < c.data.rooms.length; i++) {
      var room = c.data.rooms[i];
      var actualType = String(room.type || "").toLowerCase().trim();
      if (actualType === requestedType) {
        c.data.selectedRoom = room.sys_id;
        return;
      }
    }
  }

  function initializeFromSearch() {
    c.checkInDate = parseDate(params.checkin);
    c.checkOutDate = parseDate(params.checkout);

    var guests = parseInt(params.guests, 10);
    if (!isNaN(guests) && guests >= 1 && guests <= 10) {
      c.data.adults = guests;
    }
    c.data.children = 0;

    if (params.room_id && c.data.rooms) {
      var requestedRoomId = String(params.room_id);
      for (var i = 0; i < c.data.rooms.length; i++) {
        if (c.data.rooms[i].sys_id === requestedRoomId) {
          c.data.selectedRoom = requestedRoomId;
          break;
        }
      }
    } else {
      selectRoomByType(params.room_type);
    }

    c.data.checkIn = c.toLocalDateStr(c.checkInDate);
    c.data.checkOut = c.toLocalDateStr(c.checkOutDate);

    if (c.data.selectedRoom && c.data.checkIn && c.data.checkOut) {
      c.onFormChange();
    }
  }

  c.onFormChange = function() {
    c.data.dateError = "";
    c.data.availReason = "";
    c.data.checkIn = c.toLocalDateStr(c.checkInDate);
    c.data.checkOut = c.toLocalDateStr(c.checkOutDate);

    if (c.data.selectedRoom && c.data.checkIn && c.data.checkOut) {
      var savedRoomId = c.data.selectedRoom;
      c.data.action = "calculateEstimate";

      c.server.update().then(function() {
        if (!c.data.selectedRoom && savedRoomId) {
          c.data.selectedRoom = savedRoomId;
        }
      });
    } else {
      c.data.estimatedTotal = 0;
      c.data.nights = 0;
      c.data.isAvailable = false;
    }
  };

  c.onGuestCountChange = function() {
    if (c.data.selectedRoom) {
      var room = c.getRoomObject(c.data.selectedRoom);
      if (room && (parseInt(c.data.adults, 10) + parseInt(c.data.children || 0, 10)) > parseInt(room.capacity, 10)) {
        c.data.dateError = "Total guests exceed the maximum room capacity (" + room.capacity + " " + (room.capacity == 1 ? "guest" : "guests") + ").";
      } else {
        c.data.dateError = "";
      }
    }
  };

  c.canReview = function() {
    var hasEmail = c.data.isLoggedIn ? true : !!(c.data.guestEmail && c.data.guestEmail.trim());
    return c.data.selectedRoom &&
           c.data.checkIn &&
           c.data.checkOut &&
           c.data.guestName &&
           hasEmail &&
           c.data.isAvailable &&
           !c.data.dateError;
  };

  c.clearForm = function() {
    c.data.selectedRoom = "";
    c.checkInDate = null;
    c.checkOutDate = null;
    c.data.checkIn = "";
    c.data.checkOut = "";
    c.data.estimatedTotal = 0;
    c.data.estimatedTotalDisplay = "$0.00";
    c.data.nights = 0;
    c.data.discountAmount = 0;
    c.data.discountAmountDisplay = "$0.00";
    c.data.dateError = "";
    c.data.availReason = "";
    c.data.bookingError = "";
    c.data.isAvailable = false;
    c.data.adults = 1;
    c.data.children = 0;

    if (!c.data.isLoggedIn) {
      c.data.guestName = "";
      c.data.guestEmail = "";
    }
  };

  c.openConfirmModal = function() {
    if (c.canReview()) {
      c.data.checkIn = c.toLocalDateStr(c.checkInDate);
      c.data.checkOut = c.toLocalDateStr(c.checkOutDate);
      c.data.bookingError = "";
      c.showModal = true;
      c.bookingConfirmed = false;
    }
  };

  c.closeModal = function() {
    c.showModal = false;
  };

  c.confirmBooking = function() {
    c.isSubmitting = true;
    c.data.bookingError = "";
    c.data.checkIn = c.toLocalDateStr(c.checkInDate);
    c.data.checkOut = c.toLocalDateStr(c.checkOutDate);
    c.data.action = "createBooking";

    c.server.update().then(function() {
      c.isSubmitting = false;
      if (c.data.bookingSuccess) {
        c.bookingConfirmed = true;
      }
    });
  };

  c.resetForm = function() {
    c.clearForm();
    c.showModal = false;
    c.bookingConfirmed = false;
  };

  c.getRoomObject = function(roomId) {
    if (!c.data.rooms) return null;
    for (var i = 0; i < c.data.rooms.length; i++) {
      if (c.data.rooms[i].sys_id === roomId) return c.data.rooms[i];
    }
    return null;
  };

  c.getSelectedRoomName = function() {
    var r = c.getRoomObject(c.data.selectedRoom);
    if (!r) return "";
    return r.name || r.type || "Selected Room";
  };

  c.getSelectedRoomRate = function() {
    var r = c.getRoomObject(c.data.selectedRoom);
    return r ? r.rate : 0;
  };

  initializeFromSearch();
};

sp_widget.css:
.hotel-room-widget {
  background: #faf6ef;
  min-height: 100vh;
  margin: -20px -15px 0 -15px;
  padding-bottom: 60px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #1a2e26;
}

.hotel-room-widget .page-banner {
  background: #1f3a30;
  color: #ffffff;
  padding: 55px 20px 50px;
  text-align: center;
  margin-bottom: 40px;
}

.hotel-room-widget .banner-inner {
  max-width: 800px;
  margin: 0 auto;
}

.hotel-room-widget .page-banner .eyebrow {
  display: block;
  font-size: 0.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #e6c79c;
  margin-bottom: 8px;
  font-weight: 600;
}

.hotel-room-widget .page-banner h1 {
  font-family: Georgia, serif;
  font-size: 2.8rem;
  color: #ffffff;
  margin: 0 0 10px;
}

.hotel-room-widget .page-banner p {
  color: rgba(255, 255, 255, 0.8);
  font-size: 1rem;
  margin: 0;
}

.hotel-room-widget .booking-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.hotel-room-widget .booking-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 32px;
  align-items: start;
}

@media (max-width: 900px) {
  .hotel-room-widget .booking-layout {
    grid-template-columns: 1fr;
  }
}

.hotel-room-widget .form-card {
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 12px;
  padding: 36px;
  box-shadow: 0 4px 20px rgba(31, 58, 48, 0.06);
}

.hotel-room-widget .form-title {
  font-family: Georgia, serif;
  font-size: 2.2rem;
  color: #1f3a30;
  margin: 0 0 8px 0;
}

.hotel-room-widget .form-subtitle {
  color: #6f756f;
  font-size: 1.05rem;
  margin-bottom: 24px;
}

.hotel-room-widget .user-badge {
  background: #e8eee9;
  border: 1px solid #c8ded1;
  color: #1f3a30;
  padding: 12px 18px;
  border-radius: 8px;
  margin-bottom: 26px;
  font-size: 1rem;
  display: flex;
  align-items: center;
  gap: 10px;
}

.hotel-room-widget .user-badge.guest {
  background: #fdf6e9;
  border-color: #f1ddb6;
  color: #8a6420;
}

.hotel-room-widget .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 600px) {
  .hotel-room-widget .form-grid {
    grid-template-columns: 1fr;
  }
}

.hotel-room-widget .form-group {
  margin-bottom: 22px;
}

.hotel-room-widget .form-group label {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.8px;
  color: #1f3a30;
  margin-bottom: 8px;
}

.hotel-room-widget .form-group label .req {
  color: #b7382d;
}

.hotel-room-widget select.form-control,
.hotel-room-widget input.form-control {
  width: 100%;
  height: 48px !important;
  line-height: 1.4 !important;
  padding: 10px 14px !important;
  border: 1.5px solid #e7e1d4;
  border-radius: 8px;
  background: #faf6ef;
  font-size: 1rem !important;
  color: #1f3a30 !important;
  box-sizing: border-box;
  transition: 0.2s;
}

.hotel-room-widget input.form-control:focus,
.hotel-room-widget select.form-control:focus {
  border-color: #1f3a30;
  background: #ffffff;
  outline: none;
}

/* Side-by-Side Action Buttons */
.hotel-room-widget .form-actions-row {
  display: flex;
  gap: 14px;
  margin-top: 28px;
}

.hotel-room-widget .btn-clear {
  flex: 0 0 140px;
  height: 52px;
  background: #ffffff;
  color: #5c635c;
  border: 1.5px solid #d9e2dc;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.hotel-room-widget .btn-clear:hover {
  background: #f5f1e8;
  color: #1f3a30;
  border-color: #1f3a30;
}

.hotel-room-widget .btn-main {
  flex: 1;
  height: 52px;
  background: #1f3a30;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: 0.2s;
}

.hotel-room-widget .btn-main:hover:not(:disabled) {
  background: #162a22;
}

.hotel-room-widget .btn-main:disabled {
  background: #b2c2ba;
  cursor: not-allowed;
}

/* RIGHT: Dark Green Summary Card */
.hotel-room-widget .summary-card {
  background: #1f3a30;
  color: #ffffff;
  border-radius: 12px;
  padding: 36px 30px;
  box-shadow: 0 6px 24px rgba(31, 58, 48, 0.2);
}

.hotel-room-widget .summary-eyebrow {
  font-size: 0.8rem;
  letter-spacing: 1.5px;
  color: #e6c79c;
  font-weight: 600;
  margin-bottom: 6px;
}

.hotel-room-widget .summary-title {
  font-family: Georgia, serif;
  font-size: 1.8rem;
  color: #ffffff;
  margin: 0 0 24px 0;
}

.hotel-room-widget .summary-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  font-size: 1rem;
}

.hotel-room-widget .summary-row .label {
  color: rgba(255, 255, 255, 0.8);
}

.hotel-room-widget .summary-row .value {
  color: #ffffff;
  font-weight: 500;
  text-align: right;
}

.hotel-room-widget .discount-row .discount-val {
  color: #79d2a6;
  font-weight: 700;
}

.hotel-room-widget .badge-avail {
  background: rgba(121, 210, 166, 0.2);
  color: #79d2a6;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 700;
}

.hotel-room-widget .badge-unavail {
  background: rgba(240, 120, 120, 0.25);
  color: #ff9e9e;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 700;
}

.hotel-room-widget .avail-reason-note {
  color: #ffb8b8;
  font-size: 0.9rem;
  margin-top: 8px;
}

.hotel-room-widget .summary-divider {
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  margin: 20px 0;
}

.hotel-room-widget .total-row {
  margin-top: 16px;
}

.hotel-room-widget .total-label {
  font-size: 0.85rem;
  letter-spacing: 1.2px;
  color: #e6c79c;
  font-weight: 700;
  margin-bottom: 6px;
}

.hotel-room-widget .total-amount {
  font-family: Georgia, serif;
  font-size: 2.4rem;
  color: #ffffff;
  font-weight: 700;
}

.hotel-room-widget .total-amount.unavail-text {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1.5rem;
  color: #ff9e9e;
}

.hotel-room-widget .summary-footer-note {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.65);
  margin-top: 18px;
  line-height: 1.4;
}

/* Alerts */
.hotel-room-widget .alert-box {
  padding: 14px 18px;
  border-radius: 8px;
  margin-top: 16px;
  font-size: 0.95rem;
}

.hotel-room-widget .alert-error {
  background: #fdf2f2;
  color: #b7382d;
  border-left: 4px solid #b7382d;
}

/* Modal */
.hotel-room-widget .modal-backdrop-custom {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(31, 58, 48, 0.6);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.hotel-room-widget .modal-card {
  background: #ffffff;
  border-radius: 12px;
  max-width: 500px;
  width: 100%;
  padding: 36px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.hotel-room-widget .modal-eyebrow {
  font-size: 0.75rem;
  letter-spacing: 1.5px;
  color: #6f756f;
  font-weight: 700;
  text-transform: uppercase;
}

.hotel-room-widget .modal-title {
  font-family: Georgia, serif;
  font-size: 1.8rem;
  color: #1f3a30;
  margin: 6px 0 16px 0;
}

.hotel-room-widget .modal-price {
  font-family: Georgia, serif;
  font-size: 2.4rem;
  color: #1f3a30;
  font-weight: 700;
  margin-bottom: 20px;
}

.hotel-room-widget .modal-details {
  border-top: 1px solid #e7e1d4;
  border-bottom: 1px solid #e7e1d4;
  padding: 16px 0;
  margin-bottom: 20px;
}

.hotel-room-widget .detail-row {
  display: flex;
  justify-content: space-between;
  padding: 6px 0;
  font-size: 0.95rem;
}

.hotel-room-widget .modal-policy {
  font-size: 0.85rem;
  color: #6f756f;
  margin-bottom: 24px;
}

.hotel-room-widget .modal-btn-row {
  display: flex;
  gap: 14px;
}

.hotel-room-widget .btn-secondary {
  flex: 1;
  height: 48px;
  border: 1.5px solid #d9e2dc;
  background: #ffffff;
  color: #1f3a30;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}

.hotel-room-widget .btn-confirm {
  flex: 1;
  height: 48px;
  background: #1f3a30;
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}

.hotel-room-widget .success-ref-box {
  background: #f3f8f5;
  border: 2px dashed #79d2a6;
  border-radius: 10px;
  padding: 24px;
  text-align: center;
  margin: 20px 0;
}

.hotel-room-widget .ref-label {
  font-size: 0.8rem;
  letter-spacing: 1.5px;
  color: #6f756f;
  font-weight: 700;
}

.hotel-room-widget .ref-number {
  font-family: Georgia, serif;
  font-size: 2.2rem;
  color: #1f3a30;
  font-weight: 700;
  margin-top: 6px;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userId = gs.getUserID();
  data.userName = gs.getUserDisplayName();
  data.userEmail = gs.getUser().getEmail() || '';

  var pricingUtil = new x_2206701_hotel_0.PricingUtils();
  var resUtil = new x_2206701_hotel_0.ReservationUtils();

  // 1. Fetch active non-maintenance rooms
  data.rooms = [];
  var roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
  roomGr.orderBy('rate');
  roomGr.query();
  while (roomGr.next()) {
    try {
      if (pricingUtil.isRoomUnderMaintenance && pricingUtil.isRoomUnderMaintenance(roomGr)) {
        continue;
      }
    } catch(e) {}

    var rName = roomGr.getValue('room_name') || roomGr.getDisplayValue('room_name') || roomGr.getDisplayValue() || '';
    var rType = roomGr.getDisplayValue('room_type') || roomGr.getValue('room_type') || '';
    if (!rName) {
      rName = rType ? (rType + ' Suite') : ('Room ' + roomGr.getUniqueValue().substring(0, 5));
    }
    data.rooms.push({
      sys_id: roomGr.getUniqueValue(),
      name: rName,
      type: rType,
      capacity: parseInt(roomGr.getValue('capacity'), 10) || 2,
      rate: parseFloat(roomGr.getValue('rate')) || 0
    });
  }

  if (!input && typeof $sp !== 'undefined') {
    var urlRoomId = $sp.getParameter('room_id');
    if (urlRoomId) {
      try {
        if (pricingUtil.isRoomUnderMaintenance && pricingUtil.isRoomUnderMaintenance(urlRoomId)) {
          data.isAvailable = false;
          data.availReason = 'This room is currently under maintenance.';
        }
      } catch(e) {}
    }
  }

  function normalizeDateStr(val) {
    if (!val) return '';
    return String(val).substring(0, 10);
  }

  function getRoomBaseRate(roomId) {
    for (var i = 0; i < data.rooms.length; i++) {
      if (data.rooms[i].sys_id === roomId) return data.rooms[i].rate;
    }
    var rg = new GlideRecord('x_2206701_hotel_0_rooms');
    if (rg.get(roomId)) return parseFloat(rg.getValue('rate')) || 0;
    return 0;
  }

  if (input) {
    data.selectedRoom = input.selectedRoom;
    data.checkIn = input.checkIn;
    data.checkOut = input.checkOut;
    data.adults = input.adults;
    data.children = input.children;
    data.guestName = input.guestName || (data.isLoggedIn ? data.userName : '');
    data.guestEmail = input.guestEmail || (data.isLoggedIn ? data.userEmail : '');

    var checkInStr = normalizeDateStr(input.checkIn);
    var checkOutStr = normalizeDateStr(input.checkOut);

    // ==========================================
    // ACTION: calculateEstimate
    // ==========================================
    if (input.action === 'calculateEstimate') {
      var dIn = new GlideDate();
      dIn.setValue(checkInStr);
      var dOut = new GlideDate();
      dOut.setValue(checkOutStr);
      var dur = GlideDate.subtract(dIn, dOut);
      var nights = dur.getDayPart();

      if (nights <= 0) {
        data.dateError = 'Check-out date must be after the check-in date.';
        data.isAvailable = false;
        data.estimatedTotal = 0;
        data.discountAmount = 0;
        data.discountAmountDisplay = '$0.00';
        data.estimatedTotalDisplay = '$0.00';
        data.nights = 0;
        return;
      }

      data.dateError = '';
      data.nights = nights;

      var isAvail = true;
      var reason = '';
      try {
        var availCheck = pricingUtil.isRoomAvailable(input.selectedRoom, checkInStr, checkOutStr);
        isAvail = availCheck.available;
        reason = availCheck.reason || '';
      } catch(e) {
        var grCheck = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        grCheck.addQuery('room', input.selectedRoom);
        grCheck.addQuery('check_in_date', '<', checkOutStr);
        grCheck.addQuery('check_out_date', '>', checkInStr);
        grCheck.addQuery('reservation_status', '!=', 'cancelled');
        grCheck.query();
        if (grCheck.hasNext()) {
          isAvail = false;
          reason = 'This room is already reserved for the selected dates.';
        }
      }

      data.isAvailable = isAvail;
      data.availReason = isAvail ? '' : reason;

      if (data.isAvailable) {
        var baseRate = getRoomBaseRate(input.selectedRoom);
        var subtotal = baseRate * nights;
        var finalTotal = subtotal;

        try {
          finalTotal = parseFloat(pricingUtil.calculateRoomTotal(input.selectedRoom, nights, checkInStr));
        } catch(e) {
          finalTotal = subtotal;
        }

        var totalDiscount = Math.round(Math.max(0, subtotal - finalTotal) * 100) / 100;
        data.discountAmount = totalDiscount;
        data.discountAmountDisplay = '$' + totalDiscount.toFixed(2);
        data.estimatedTotal = finalTotal;
        data.estimatedTotalDisplay = '$' + finalTotal.toFixed(2);
      } else {
        data.discountAmount = 0;
        data.discountAmountDisplay = '$0.00';
        data.estimatedTotal = 0;
        data.estimatedTotalDisplay = 'Unavailable';
      }
    }

    // ==========================================
    // ACTION: createBooking
    // ==========================================
    if (input.action === 'createBooking') {
      var targetRoom = input.selectedRoom || data.selectedRoom;

      try {
        var createAvail = pricingUtil.isRoomAvailable(targetRoom, checkInStr, checkOutStr);
        if (!createAvail.available) {
          data.bookingSuccess = false;
          data.bookingError = createAvail.reason;
          data.isAvailable = false;
          data.availReason = createAvail.reason;
          return;
        }
      } catch(e) {}

      var calcNights = 1;
      try {
        calcNights = resUtil.calculateDays(checkInStr, checkOutStr);
      } catch(e) {
        var d1 = new GlideDate(); d1.setValue(checkInStr);
        var d2 = new GlideDate(); d2.setValue(checkOutStr);
        calcNights = Math.max(1, GlideDate.subtract(d1, d2).getDayPart());
      }

      var calcTotal = 0;
      try {
        calcTotal = pricingUtil.calculateRoomTotal(targetRoom, calcNights, checkInStr);
      } catch(e) {
        var br = getRoomBaseRate(targetRoom);
        calcTotal = br * calcNights;
      }

      var grBook = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
      grBook.initialize();

      if (grBook.isValidField('room')) grBook.setValue('room', targetRoom);
      if (grBook.isValidField('check_in_date')) grBook.setValue('check_in_date', checkInStr);
      if (grBook.isValidField('check_out_date')) grBook.setValue('check_out_date', checkOutStr);
      if (grBook.isValidField('guest_name')) grBook.setValue('guest_name', input.guestName || data.userName);
      if (grBook.isValidField('guest_email')) grBook.setValue('guest_email', input.guestEmail || data.userEmail || '');

      if (grBook.isValidField('number_of_adults')) grBook.setValue('number_of_adults', parseInt(input.adults, 10) || 1);
      if (grBook.isValidField('adults')) grBook.setValue('adults', parseInt(input.adults, 10) || 1);
      if (grBook.isValidField('number_of_children')) grBook.setValue('number_of_children', parseInt(input.children, 10) || 0);
      if (grBook.isValidField('children')) grBook.setValue('children', parseInt(input.children, 10) || 0);

      if (grBook.isValidField('number_of_days')) grBook.setValue('number_of_days', calcNights);
      if (grBook.isValidField('total_payment')) grBook.setValue('total_payment', calcTotal);
      if (grBook.isValidField('total_amount')) grBook.setValue('total_amount', calcTotal);
      if (grBook.isValidField('reservation_status')) grBook.setValue('reservation_status', 'pending');

      if (data.userId) {
        if (grBook.isValidField('registered_user')) grBook.setValue('registered_user', data.userId);
        if (grBook.isValidField('user')) grBook.setValue('user', data.userId);
      }

      var newId = grBook.insert();
      if (newId) {
        data.bookingSuccess = true;
        var resGr = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        if (resGr.get(newId)) {
          data.reservationDisplayNumber = resGr.getValue('number') || newId;
        } else {
          data.reservationDisplayNumber = newId;
        }
      } else {
        data.bookingSuccess = false;
        data.bookingError = 'Could not create reservation. Please ensure your user account has permission to book.';
      }
    }
  }
})();
